using System.Collections;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CorruptedAnchorAction", menuName = "Data/Battle/Battle Actions/Enemy/CorruptedAnchor Action")]
public class CorruptedAnchorAction : BattleAction
{
	[Header("Purify Action")]
	[SerializeField]
	private CorruptAction corruptAction;

	[Header("Player Game Object")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[Header("VFX")]
	[SerializeField]
	private float corruptedAnchorVFXDelay;

	[SerializeField]
	private float sfxDelay;

	public CorruptAction CorruptAction => corruptAction;

	private float GetPlayerCurrentCorruption()
	{
		return playerGameObjectReference.value.GetComponent<CorruptionStats>().CurrentCorruption;
	}

	public int GetCurrentCorruptionAmount()
	{
		return 6 - (int)GetPlayerCurrentCorruption();
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CorruptedAnchorVFX(target, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			corruptAction.CastTargetAmount(target, GetCurrentCorruptionAmount(), source);
		}
	}

	private IEnumerator CorruptedAnchorVFX(GameObject target, GameObject source)
	{
		PlaySFX();
		yield return new WaitForSeconds(sfxDelay);
		SpawnVFX(GetVFXOwnerPosition(target), 5f);
		yield return new WaitForSeconds(corruptedAnchorVFXDelay);
		corruptAction.CastTargetAmount(target, GetCurrentCorruptionAmount(), source);
	}
}
